(function(){
  const w0 = W(), h0 = H();
  const cx = w0/2, cy = h0/2;
  const safeR = Math.min(w0,h0)*0.24;
  const colors = PALETTE;

  const clusters = [
    {x: w0*0.16, y: h0*0.18, r: w0*0.16},
    {x: w0*0.86, y: h0*0.84, r: w0*0.16}
  ];
  const puffs = [];
  clusters.forEach(c=>{
    const n = 55;
    for(let i=0;i<n;i++){
      const ang = Math.random()*Math.PI*2;
      const rad = Math.random()*c.r;
      puffs.push({
        cx: c.x, cy: c.y,
        baseAng: ang, baseRad: rad,
        size: 6+Math.random()*22,
        speed: 0.06+Math.random()*0.08,
        phase: Math.random()*Math.PI*2,
        color: colors[Math.floor(Math.random()*colors.length)],
        alpha: 0.25+Math.random()*0.4
      });
    }
  });

  const seeds = [];
  const seedCount = 24;
  function makeSeed(){
    const side = Math.random()<0.5;
    const startX = side? -50 : w0+50;
    const startY = Math.random()*h0;
    return {
      x: startX, y: startY,
      vx: (side? 1:-1) * (0.25+Math.random()*0.35),
      vy: (Math.random()-0.5)*0.15,
      size: 3+Math.random()*6,
      trail: [],
      color: colors[Math.floor(Math.random()*colors.length)],
      wob: Math.random()*Math.PI*2
    };
  }
  for(let i=0;i<seedCount;i++){ seeds.push(makeSeed()); }

  function hexA(hex, a){
    const h = hex.replace('#','');
    const r = parseInt(h.substring(0,2),16);
    const g = parseInt(h.substring(2,4),16);
    const b = parseInt(h.substring(4,6),16);
    return 'rgba('+r+','+g+','+b+','+a+')';
  }

  let t = 0;
  function frame(){
    t += 1;
    const w2 = W(), h2 = H();
    ctx.clearRect(0,0,w2,h2);

    puffs.forEach(p=>{
      const ang = p.baseAng + t*p.speed*0.01;
      const rad = p.baseRad + Math.sin(t*0.01+p.phase)*8;
      const x = p.cx + Math.cos(ang)*rad;
      const y = p.cy + Math.sin(ang)*rad*0.7;
      const a = p.alpha * (0.7+0.3*Math.sin(t*0.02+p.phase));
      const grad = ctx.createRadialGradient(x,y,0,x,y,p.size);
      grad.addColorStop(0, hexA(p.color, a));
      grad.addColorStop(1, hexA(p.color, 0));
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x,y,p.size,0,Math.PI*2);
      ctx.fill();
    });

    seeds.forEach((s,idx)=>{
      const dx = s.x-cx, dy=s.y-cy;
      const dist = Math.sqrt(dx*dx+dy*dy);
      if(dist < safeR){
        const push = (safeR-dist)*0.02;
        const nx = dx/(dist||1), ny=dy/(dist||1);
        s.x += nx*push;
        s.y += ny*push;
      }
      s.wob += 0.02;
      s.x += s.vx + Math.sin(s.wob)*0.15;
      s.y += s.vy + Math.cos(s.wob*0.8)*0.1;

      s.trail.push({x:s.x,y:s.y});
      if(s.trail.length>18) s.trail.shift();

      for(let j=0;j<s.trail.length;j++){
        const pt = s.trail[j];
        const a = (j/s.trail.length)*0.35;
        ctx.beginPath();
        ctx.fillStyle = hexA(s.color,a);
        ctx.arc(pt.x, pt.y, s.size*(j/s.trail.length), 0, Math.PI*2);
        ctx.fill();
      }

      ctx.save();
      ctx.shadowColor = s.color;
      ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.fillStyle = hexA(s.color, 0.85);
      ctx.arc(s.x, s.y, s.size, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();

      if(s.x < -60 || s.x > w2+60 || s.y<-60 || s.y>h2+60){
        seeds[idx] = makeSeed();
      }
    });

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
